"""Export an offline interactive feature-to-feature explorer (no external services)."""
from pathlib import Path
import json
from feature_content import FEATURES
root=Path(__file__).resolve().parents[1]
data=json.dumps(FEATURES,ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MRM · Detailed feature connections</title>
<style>:root{color-scheme:dark;--bg:#111b35;--panel:#1b2846;--line:#34435f;--ink:#f7f9ff;--muted:#bbc8df;--cyan:#62dae8;--gold:#e8c578}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 system-ui,Arial,sans-serif}aside{position:fixed;inset:0 auto 0 0;width:300px;background:#14203b;border-right:1px solid var(--line);padding:24px 18px;overflow:auto}h1{font-size:18px;margin:0 0 6px}aside p{color:var(--muted);font-size:12px}input{width:100%;padding:12px;border:1px solid var(--line);background:var(--bg);color:white;border-radius:8px;margin:14px 0}button{font:inherit;cursor:pointer;color:inherit}nav button{display:block;text-align:left;width:100%;background:none;border:0;border-radius:7px;padding:10px 12px;color:var(--muted);font-size:13px}nav button:hover,nav button.active{background:#263b55;color:var(--cyan)}main{margin-left:300px;padding:30px 36px;max-width:1720px}header p{color:var(--cyan);letter-spacing:.09em;font-size:11px;font-weight:700}h2{font-size:29px;line-height:1.25;margin:8px 0 16px}.why{font-size:18px;max-width:1100px;color:#dde5f4}.scope{padding:10px 14px;border-left:3px solid var(--cyan);background:var(--panel);color:var(--muted);font-size:13px;margin:20px 0}svg{display:block;width:100%;height:auto;background:#14203b;border:1px solid var(--line);border-radius:12px}.node{cursor:pointer}.node:hover rect{stroke:#e8c578}.lower{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px}.box{padding:20px;background:var(--panel);border:1px solid var(--line);border-radius:10px}.box h3{font-size:13px;color:var(--gold);margin:0 0 8px}.box p{margin:0;color:var(--muted);font-size:14px}.related button{border:1px solid var(--line);background:#23364f;border-radius:7px;padding:8px 12px;margin:5px;font-size:12px}.hint{color:var(--muted);font-size:12px}.toolbar{display:flex;gap:12px;margin:18px 0}.toolbar button{padding:8px 14px;background:var(--panel);border:1px solid var(--line);border-radius:6px}footer{font-size:12px;color:var(--muted);margin-top:30px}@media(max-width:900px){aside{position:relative;width:auto;height:auto;max-height:320px}main{margin:0;padding:24px 16px}.lower{grid-template-columns:1fr}h2{font-size:24px}}@media print{aside,.toolbar,.hint{display:none}main{margin:0;padding:10px}.lower{break-inside:avoid}body{print-color-adjust:exact}}</style>
<aside><h1>MRM feature connections</h1><p>52 individual maps · all-Muslim platform<br>Choose a feature, then follow its connections.</p><label for="q">Find a feature</label><input id="q" placeholder="Search care, Quran, teacher…"><nav id="list" aria-label="Features"></nav></aside>
<main><header><p>MRM DIGITAL COMMUNITY PLATFORM / DETAILED CONNECTIONS</p><h2 id="title"></h2><div class="why" id="why"></div></header><div class="scope" id="scope"></div><div class="toolbar"><button id="prev">← Previous feature</button><button id="next">Next feature →</button><button onclick="window.print()">Print this map</button></div><p class="hint">Select a connected feature box to open its own map. Arrows name the relationship, not unrestricted data sharing.</p><svg id="graph" viewBox="0 0 1200 485" role="img" aria-label="Directed feature connections"></svg><div class="lower"><section class="box"><h3>WHAT TO VERIFY</h3><p id="measure"></p></section><section class="box"><h3>EVIDENCE / POLICY NOTE</h3><p id="decision"></p></section></div><section class="box" style="margin-top:20px"><h3>RELATED FEATURES</h3><div class="related" id="related"></div></section><footer>Proposed product relationships. MVP images do not verify production behaviour. Marketplace excluded; core member assistance and volunteering are not behind teacher subscriptions. Extended financial concepts require separate approval.</footer></main>
<script>const features=DATA;const byKey=Object.fromEntries(features.map(f=>[f.key,f]));let selected='matching';const el=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));const label=s=>s.replaceAll('_',' ');function wrap(s,n){let out=[],l='';s.split(' ').forEach(w=>{if((l+' '+w).trim().length>n&&l){out.push(l);l=w}else l=(l+' '+w).trim()});if(l)out.push(l);return out}function text(s,x,y,n,size,color,bold){return '<text x="'+x+'" y="'+y+'" fill="'+color+'" font-size="'+size+'" font-weight="'+(bold?700:400)+'">'+wrap(s,n).map((l,i)=>'<tspan x="'+x+'" dy="'+(i?size*1.32:0)+'">'+esc(l)+'</tspan>').join('')+'</text>'}function set(k){if(!byKey[k])return;selected=k;render();history.replaceState(null,'','#'+k)}function render(){let f=byKey[selected];el('title').textContent=f.title;el('why').textContent=f.why;el('scope').textContent=f.status+' · Full presentation page '+f.page+' · Atlas map '+f.atlas_page;el('measure').textContent=f.measure;el('decision').textContent=f.decision;let q=el('q').value.toLowerCase();el('list').replaceChildren();features.filter(a=>(a.key+' '+a.title+' '+a.status).toLowerCase().includes(q)).forEach(a=>{let b=document.createElement('button');b.textContent=String(a.atlas_page).padStart(2,'0')+'  '+label(a.key);b.className=a.key===selected?'active':'';b.onclick=()=>set(a.key);el('list').append(b)});let color=f.kind==='extension'?'#c2a3ff':'#62dae8';let pos=f.nodes.map((n,i)=>({x:18+(i%3)*402,y:i<3?34:280,w:330,h:144}));let svg='<defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="'+color+'"/></marker></defs>';f.edges.forEach(([a,b,l])=>{let p=pos[a],r=pos[b],pc={x:p.x+p.w/2,y:p.y+p.h/2},rc={x:r.x+r.w/2,y:r.y+r.h/2},pts;if(Math.abs(pc.y-rc.y)<1)pts=pc.x<rc.x?[[p.x+p.w,pc.y],[r.x,rc.y]]:[[p.x,pc.y],[r.x+r.w,rc.y]];else if(Math.abs(pc.x-rc.x)<1)pts=pc.y<rc.y?[[pc.x,p.y+p.h],[rc.x,r.y]]:[[pc.x,p.y],[rc.x,r.y+r.h]];else if(pc.y<rc.y){let st=[pc.x,p.y+p.h],en=[rc.x,r.y],my=(st[1]+en[1])/2;pts=[st,[st[0],my],[en[0],my],en]}else{let side=pc.x<rc.x,st=[side?p.x+p.w:p.x,pc.y],en=[side?r.x:r.x+r.w,rc.y],mx=(st[0]+en[0])/2;pts=[st,[mx,st[1]],[mx,en[1]],en]}svg+='<polyline points="'+pts.map(a=>a.join(',')).join(' ')+'" fill="none" stroke="'+color+'" stroke-width="1.7" marker-end="url(#a)"/>';let seg=pts.slice(0,-1).map((p,i)=>[p,pts[i+1]]).sort((a,b)=>(Math.abs(b[0][0]-b[1][0])+Math.abs(b[0][1]-b[1][1]))-(Math.abs(a[0][0]-a[1][0])+Math.abs(a[0][1]-a[1][1])))[0],mx=(seg[0][0]+seg[1][0])/2,my=(seg[0][1]+seg[1][1])/2;svg+='<rect x="'+(mx-44)+'" y="'+(my-25)+'" width="88" height="21" fill="#111b35"/>'+'<text x="'+mx+'" y="'+(my-10)+'" fill="'+color+'" font-size="'+(l.length>12?9:10)+'" font-weight="700" text-anchor="middle">'+esc(l)+'</text>'});f.nodes.forEach((n,i)=>{let p=pos[i];svg+='<g class="node" data-ref="'+esc(n.ref)+'" tabindex="0" role="button" aria-label="Open '+esc(n.title)+'"><rect x="'+p.x+'" y="'+p.y+'" width="'+p.w+'" height="'+p.h+'" rx="10" fill="'+(i===1?'#233b55':'#1b2846')+'" stroke="'+(i===1?color:'#34435f')+'"/>'+text(n.title,p.x+18,p.y+29,32,17,'#f7f9ff',true)+text(n.body,p.x+18,p.y+85,43,13,'#bbc8df',false)+'</g>'});el('graph').innerHTML=svg;el('graph').querySelectorAll('.node').forEach(n=>{n.onclick=()=>set(n.dataset.ref);n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();set(n.dataset.ref)}}});el('related').replaceChildren();[...new Set(f.nodes.map(n=>n.ref))].filter(k=>k!==f.key&&byKey[k]).forEach(k=>{let b=document.createElement('button');b.textContent=label(k);b.onclick=()=>set(k);el('related').append(b)});document.title='MRM · '+label(selected)}el('q').oninput=render;el('prev').onclick=()=>{let i=features.findIndex(f=>f.key===selected);set(features[(i+features.length-1)%features.length].key)};el('next').onclick=()=>{let i=features.findIndex(f=>f.key===selected);set(features[(i+1)%features.length].key)};if(byKey[location.hash.slice(1)])selected=location.hash.slice(1);render();</script></html>'''
(root/'Interactive_Feature_Explorer.html').write_text(page.replace('DATA',data,1))
print('Exported offline explorer for',len(FEATURES),'features.')
